static int cmpChar(const void *a, const void *b) {
  return *(char *)a - *(char *)b;
}

static void backtrack(char *s, int n, bool *used, char *cur, int depth, char **res, int *size) {
  if (depth == n) {
    cur[n] = '\0';
    res[*size] = strdup(cur);
    (*size)++;
    return;
  }
  for (int i = 0; i < n; i++) {
    if (used[i]) continue;
    if (i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;
    used[i] = true;
    cur[depth] = s[i];
    backtrack(s, n, used, cur, depth + 1, res, size);
    used[i] = false;
  }
}

char **permutation(char *S, int *returnSize) {
  int n = strlen(S);
  qsort(S, n, sizeof(char), cmpChar);
  char **res = (char **)malloc(sizeof(char *) * 100000);
  bool *used = (bool *)calloc(n, sizeof(bool));
  char *cur = (char *)malloc(n + 1);
  *returnSize = 0;
  backtrack(S, n, used, cur, 0, res, returnSize);
  free(used);
  free(cur);
  return res;
}

class Solution {
  void backtrack(string &s, vector<bool> &used, string &cur, vector<string> &res) {
    if (cur.size() == s.size()) {
      res.push_back(cur);
      return;
    }
    for (size_t i = 0; i < s.size(); i++) {
      if (used[i]) continue;
      if (i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;
      used[i] = true;
      cur.push_back(s[i]);
      backtrack(s, used, cur, res);
      cur.pop_back();
      used[i] = false;
    }
  }

public:
  vector<string> permutation(string S) {
    sort(S.begin(), S.end());
    vector<string> res;
    vector<bool> used(S.size(), false);
    string cur;
    backtrack(S, used, cur, res);
    return res;
  }
};

func permutation(S string) []string {
	b := []byte(S)
	sort.Slice(b, func(i, j int) bool { return b[i] < b[j] })
	var res []string
	n := len(b)
	used := make([]bool, n)
	var cur []byte
	var dfs func()
	dfs = func() {
		if len(cur) == n {
			res = append(res, string(cur))
			return
		}
		for i := 0; i < n; i++ {
			if used[i] {
				continue
			}
			if i > 0 && b[i] == b[i-1] && !used[i-1] {
				continue
			}
			used[i] = true
			cur = append(cur, b[i])
			dfs()
			cur = cur[:len(cur)-1]
			used[i] = false
		}
	}
	dfs()
	return res
}

class Solution {
  private void backtrack(char[] s, boolean[] used, StringBuilder cur, List<String> res) {
    if (cur.length() == s.length) {
      res.add(cur.toString());
      return;
    }
    for (int i = 0; i < s.length; i++) {
      if (used[i]) continue;
      if (i > 0 && s[i] == s[i - 1] && !used[i - 1]) continue;
      used[i] = true;
      cur.append(s[i]);
      backtrack(s, used, cur, res);
      cur.deleteCharAt(cur.length() - 1);
      used[i] = false;
    }
  }

  public String[] permutation(String S) {
    char[] s = S.toCharArray();
    Arrays.sort(s);
    List<String> res = new ArrayList<>();
    backtrack(s, new boolean[s.length], new StringBuilder(), res);
    return res.toArray(new String[0]);
  }
}

class Solution:
    def permutation(self, S: str) -> List[str]:
        s = sorted(S)
        n = len(s)
        res = []
        used = [False] * n
        cur = []

        def dfs():
            if len(cur) == n:
                res.append("".join(cur))
                return
            for i in range(n):
                if used[i]:
                    continue
                if i > 0 and s[i] == s[i - 1] and not used[i - 1]:
                    continue
                used[i] = True
                cur.append(s[i])
                dfs()
                cur.pop()
                used[i] = False

        dfs()
        return res

impl Solution {
  pub fn permutation(s: String) -> Vec<String> {
    let mut chars: Vec<char> = s.chars().collect();
    chars.sort();
    let n = chars.len();
    let mut used = vec![false; n];
    let mut cur = String::new();
    let mut res = vec![];
    fn dfs(
      chars: &[char],
      used: &mut Vec<bool>,
      cur: &mut String,
      res: &mut Vec<String>,
    ) {
      if cur.len() == chars.len() {
        res.push(cur.clone());
        return;
      }
      for i in 0..chars.len() {
        if used[i] {
          continue;
        }
        if i > 0 && chars[i] == chars[i - 1] && !used[i - 1] {
          continue;
        }
        used[i] = true;
        cur.push(chars[i]);
        dfs(chars, used, cur, res);
        cur.pop();
        used[i] = false;
      }
    }
    dfs(&chars, &mut used, &mut cur, &mut res);
    res
  }
}

const permutation = (S: string): string[] => {
  const s = S.split('').sort();
  const n = s.length;
  const res: string[] = [];
  const used: boolean[] = new Array(n).fill(false);
  const cur: string[] = [];
  const dfs = () => {
    if (cur.length === n) {
      res.push(cur.join(''));
      return;
    }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      if (i > 0 && s[i] === s[i - 1] && !used[i - 1]) continue;
      used[i] = true;
      cur.push(s[i]);
      dfs();
      cur.pop();
      used[i] = false;
    }
  };
  dfs();
  return res;
};
